/* Portable legacy archive: every claim and every preview has source evidence. */
'use strict';
window.VoidfallLegacy=(()=>{
 const L=window.VOIDFALL_LEGACY;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const order=['All content','Enemies','Bosses','Weapons','Evolutions','Maps','Cards','Upgrades','Forms','Characters','Abilities','Assets','Audio','Challenges','Elite modifiers','Events','Source files'];
 const labels={Cards:'Passive cards',Upgrades:'Early upgrade cards',Characters:'Early characters',Forms:'Player forms',Assets:'Original artwork',Audio:'Sound cues'};
 const glyphs={Weapons:'⊕',Evolutions:'◇',Cards:'▣',Upgrades:'▣',Audio:'♪',Abilities:'✦','Elite modifiers':'✧',Challenges:'◷','Source files':'⌘'};
 const statusLabel=s=>s==='Gaps'?'Missing + changed':s==='Present'?'Present ID':s==='Review'?'Needs review':s;
 const statusClass=s=>s.toLowerCase();
 const selected=(r,s)=>s.legacyVersion==='all'?r.versions.at(-1):r.versions.find(v=>v.version===s.legacyVersion);
 const image=(url,name,className='')=>url?`<img class="${className}" src="${esc(url)}" alt="${esc(name)}" loading="lazy">`:`<span class="archive-glyph" aria-label="No standalone image">${glyphs[name]||'◇'}</span>`;
 const source=s=>s?`<a class="source-path" href="${esc(s.url)}?raw=1" target="_blank" rel="noopener">${esc((s.version?s.version+' / ':'')+s.path)}:${s.line} ↗</a>`:'';
 const matches=(r,q)=>!q||[r.name,r.key,r.category,r.description,r.current?.name,r.current?.id,...r.versions.flatMap(v=>[v.name,v.description,v.source.path,...(v.aliases||[])])].join(' ').toLowerCase().includes(q.toLowerCase());
 const statData=v=>Object.entries(v).filter(([k,val])=>typeof val==='number'&&!['rank','line'].includes(k));
 const table=data=>`<table class="stat-table">${data.map(([k,val])=>`<tr><td>${esc(k.replace(/([a-z])([A-Z])/g,'$1 $2'))}</td><td>${esc(val)}</td></tr>`).join('')}</table>`;
 function card(r,s){
  const v=selected(r,s),preview=v.image||r.image,versions=r.versions.map(v=>v.version).join(' · '),hasCurrent=!!r.current;
  return `<button class="archive-card" data-legacy="${esc(r.id)}"><div class="archive-card-top"><span class="status-tag ${statusClass(r.status)}">${statusLabel(r.status)}</span><span class="archive-versions">${versions}</span></div><div class="archive-comparison ${r.category==='Maps'||r.category==='Bosses'?'landscape':''}"><div>${image(preview,r.name)}<small>LEGACY ${v.version.toUpperCase()}</small></div>${hasCurrent?`<div class="comparison-arrow">→</div><div>${image(r.current.image,r.current.name)}<small>UNITY</small></div>`:''}</div><div class="archive-card-copy"><span class="archive-kind">${esc(labels[r.category]||r.category)}</span><h2>${esc(r.name)}</h2><p>${esc(v.description||r.description||r.reason)}</p>${hasCurrent?`<div class="paired-label">${r.status==='Review'?'Possible relation':'Current counterpart'} <strong>${esc(r.current.name)}</strong></div>`:`<div class="paired-label">${r.category==='Assets'?'Original source render':r.category==='Audio'?'Original synthesis code':r.category==='Maps'?'No named current arena':'No named current entry'}</div>`}<span class="archive-inspect">${v.ranks?v.ranks.length+' authored ranks · ':''}${r.versions.length>1?'Compare history':'Inspect source'} ↗</span></div></button>`;
 }
 function overview(s){
  const counts=L.counts,artwork=L.records.filter(r=>r.category==='Enemies'&&r.status==='Missing').slice(0,8);
  return `<div class="archive-hero"><div><div class="eyebrow">THE EARLY VOID / 5 SOURCE VERSIONS</div><h2>Know what’s here.<br><span>See what’s left behind.</span></h2><p>Explore the original content, compare it with Unity, and decide what deserves a return.</p><div class="archive-hero-meta"><span>${counts.contentFamilies} content identities</span><span>${counts.uniqueRenders} original renders</span><span>${counts.sourceFiles} source files</span></div></div><div class="archive-constellation" aria-label="Original missing enemy artwork">${artwork.map(r=>image(r.image,r.name)).join('')}</div></div><div class="archive-status-summary">${['Missing','Adapted','Present','Review'].map(status=>`<button data-legacy-status="${status}" data-legacy-kind="All content"><strong>${counts[status]||0}</strong><span>${statusLabel(status)}</span><small>${status==='Missing'?'Named entry absent':status==='Adapted'?'Current definition differs':status==='Present'?'Stable ID still exists':'Possible relation'}</small></button>`).join('')}</div><div class="archive-evidence-note"><span class="evidence-dot"></span><p>These labels describe catalog evidence. A present ID does not imply identical art or behavior. Similarities stay under <strong>Needs review</strong>; migration choices remain yours.</p></div><div class="subheading"><h2>Content at a glance</h2><small>Union across every version</small></div><div class="archive-category-grid">${order.filter(c=>L.summary[c]).map(c=>{const n=L.summary[c];return `<button data-legacy-kind="${esc(c)}"><span>${esc(labels[c]||c)} <span>↗</span></span><strong>${n.total}</strong><small>${n.Missing?`${n.Missing} missing`:''}${n.Missing&&n.Adapted?' · ':''}${n.Adapted?`${n.Adapted} adapted`:''}${!n.Missing&&!n.Adapted?`${n.Review||n.Present} ${n.Review?'to review':'present'}`:''}</small><div class="coverage-track">${['Present','Adapted','Review','Missing'].map(k=>n[k]?`<i class="${statusClass(k)}" style="width:${n[k]/n.total*100}%" title="${n[k]} ${statusLabel(k)}"></i>`:'').join('')}</div></button>`}).join('')}</div><div class="subheading"><h2>Five stages of Voidfall</h2><small>Source changes preserved</small></div><div class="version-timeline">${L.versions.map(v=>`<button data-legacy-version="${v.id}"><span>${v.id.toUpperCase()}</span><h3>${v.name}</h3><p>${v.enemies} enemies · ${v.weapons} weapons<br>${v.cards} passives · ${v.forms} forms</p><small>${v.changes.length} ${v.id==='v1'?'initial':'changed'} files ↗</small></button>`).join('')}</div><details class="scope-details"><summary>Scope and comparison rules</summary><p>${esc(L.scope)}</p><p>${esc(L.note)}</p><p>${esc(L.renderer)}</p></details>`;
 }
 function render(s){
  if(!s.legacyKind)s.legacyKind='Overview';if(!s.legacyVersion)s.legacyVersion='all';if(!s.legacyStatus)s.legacyStatus='All';
  const primary=['Overview','All content','Enemies','Weapons','Maps','Assets'];
  const other=order.filter(c=>!primary.includes(c));
  const controls=`<div class="archive-toolbar"><div class="archive-section-pills">${primary.map(c=>`<button data-legacy-kind="${c}" class="${c===s.legacyKind?'active':''}">${labels[c]||c}${L.summary[c]?` <small>${L.summary[c].total}</small>`:''}</button>`).join('')}<select class="selector" id="legacy-kind" aria-label="More legacy categories"><option value="" disabled ${primary.includes(s.legacyKind)?'selected':''}>More content</option>${other.map(c=>`<option value="${c}" ${s.legacyKind===c?'selected':''}>${labels[c]||c}${L.summary[c]?' ('+L.summary[c].total+')':''}</option>`).join('')}</select></div></div>`;
  if(s.legacyKind==='Overview')return controls+overview(s);
  const status=s.legacyStatus;
  const filtered=L.records.filter(r=>(s.legacyKind==='All content'?r.category!=='Assets':r.category===s.legacyKind)&&selected(r,s)&&(status==='All'||status==='Gaps'?status==='All'||r.status!=='Present':r.status===status)&&matches(r,s.q));
  const files=L.files.filter(f=>(s.legacyVersion==='all'||f.version===s.legacyVersion)&&(!s.q||f.path.toLowerCase().includes(s.q.toLowerCase())));
  const filter=`<div class="archive-filter-row"><div class="archive-status-tabs">${['All','Gaps','Missing','Adapted','Present','Review'].map(k=>`<button data-legacy-status="${k}" class="${status===k?'active':''}">${statusLabel(k)}</button>`).join('')}</div><select class="selector" id="legacy-version" aria-label="Legacy version"><option value="all">All five versions</option>${L.versions.map(v=>`<option value="${v.id}" ${v.id===s.legacyVersion?'selected':''}>${v.name}</option>`).join('')}</select><label class="search archive-search"><input type="search" id="search" aria-label="Search legacy" placeholder="Search names, IDs, source…" value="${esc(s.q)}"></label></div>`;
  const body=s.legacyKind==='Source files'?`<div class="archive-source-list">${files.map(f=>`<a href="${esc(f.url)}?raw=1" target="_blank" rel="noopener"><span>${f.version.toUpperCase()}</span><strong>${esc(f.path)}</strong><small>${Math.round(f.bytes/1024)} KB ↗</small></a>`).join('')}</div>`:filtered.length?`<div class="archive-grid">${filtered.slice(0,s.limit).map(r=>card(r,s)).join('')}</div>${filtered.length>s.limit?'<button class="more-button" id="load-more">Load more legacy content</button>':''}`:'<div class="empty"><h2>No matching legacy entries</h2><p>Try a different version, status or search.</p></div>';
  return controls+filter+`<div class="archive-context"><span>${s.legacyKind==='Source files'?files.length:filtered.length} ${s.legacyKind==='Source files'?'files':'identities'} · ${s.legacyVersion==='all'?'v1–v5 union':s.legacyVersion.toUpperCase()}</span><span>Original art · inspect to compare versions and every rank</span></div>`+body+`<details class="scope-details"><summary>How to interpret migration status</summary><p>${esc(L.note)}</p></details>`;
 }
 function details(id,s){
  const r=L.records.find(r=>r.id===id);if(!r)return;const selectedVersion=selected(r,s)||r.versions.at(-1),cur=r.current;
  const content=`<div class="legacy-detail-header"><span class="status-tag ${statusClass(r.status)}">${statusLabel(r.status)}</span><div class="eyebrow">LEGACY VOIDFALL / ${esc(r.category)}</div><h2 id="detail-title">${esc(r.name)}</h2><p>${esc(r.reason)}</p></div><div class="detail-body"><div class="detail-comparison"><section><h3>Legacy ${selectedVersion.version.toUpperCase()}</h3><div class="detail-art">${image(selectedVersion.image||r.image,r.name)}</div><p>${esc(selectedVersion.description||r.description||'Original source entry.')}</p>${statData(selectedVersion).length?`<details class="scope-details"><summary>Authored legacy values</summary>${table(statData(selectedVersion))}</details>`:''}</section><section><h3>${cur?r.status==='Review'?'Possible Unity relation':'Current Unity counterpart':'Current Unity'}</h3><div class="detail-art">${cur?image(cur.image,cur.name):'<span class="no-counterpart">'+(r.status==='Missing'?'No named catalog entry':'Needs source review')+'</span>'}</div>${cur?`<h4>${esc(cur.name)}</h4><p>${esc(cur.description||'Current catalog entry; inspect the Unity source below.')}</p>${cur.stats?`<details class="scope-details"><summary>Authored current values</summary>${table(Object.entries(cur.stats).filter(([k,val])=>val!==null&&typeof val!=='object'))}</details>`:''}${source(cur.source)}`:''}</section></div>${selectedVersion.artNote?`<p class="art-note">${esc(selectedVersion.artNote)}</p>`:''}${cur?.sourceExcerpt?`<details class="source-excerpt"><summary>Inspected Unity source</summary><pre>${esc(cur.sourceExcerpt)}</pre></details>`:''}<div class="subheading"><h3>Version history</h3><small>${r.versions.length} source versions</small></div>${[...r.versions].reverse().map(v=>`<details class="legacy-version-detail" ${v.version===selectedVersion.version?'open':''}><summary><span>${v.version.toUpperCase()}</span> ${esc(v.name||r.name)} <small>${v.ranks?v.ranks.length+' ranks':''}</small></summary><div>${v.image?`<div class="history-art">${image(v.image,r.name)}</div>`:''}<p>${esc(v.description||'')}</p>${v.availability?`<p class="availability">${esc(v.availability)}</p>`:''}${table(statData(v))}${v.baseStats?table(Object.entries(v.baseStats)):''}${v.stats?table(Object.entries(v.stats)):''}${v.magic?`<h4>${esc(v.magic.name)}</h4><p>${esc(v.magic.desc)}</p>${table(statData(v.magic))}`:''}${v.condition?`<h4>Evolution condition</h4>${table(Object.entries(v.condition))}`:''}${v.ranks?`<h4>Every authored rank</h4><div class="legacy-rank-list">${v.ranks.map(rank=>`<div><strong>${rank.rank}</strong><span>${esc(rank.description||Object.entries(rank.stats||{}).map(([k,val])=>k+': '+val).join(' · '))}</span></div>`).join('')}</div>`:''}${source(v.source)}<details class="source-excerpt"><summary>Original source excerpt</summary><pre>${esc(v.sourceExcerpt)}</pre></details><span class="source-path">Stable legacy ID: ${esc(r.key)}</span>${v.aliases?`<p class="art-note">Uses: ${esc(v.aliases.join(', '))}</p>`:''}</div></details>`).join('')}</div>`;
  const dialog=document.querySelector('#details');document.querySelector('#detail-content').innerHTML=content;dialog.classList.add('legacy-dialog');dialog.showModal();dialog.querySelector('.close-detail').focus({preventScroll:true});dialog.scrollTop=0;
 }
 return {render,details,count:L.counts.contentFamilies};
})();
